    if (2 < u_CFParamI5) {
        tex_z += u_CFParamF5 + (1.0 - u_CFParamF5) * u_CFParamF4 * sampleDepthComp(u_CFParamTexture_2, uv, u_CFParamI2);
    }
    if (3 < u_CFParamI5) {
        tex_z += u_CFParamF7 + (1.0 - u_CFParamF7) * u_CFParamF6 * sampleDepthComp(u_CFParamTexture_3, uv, u_CFParamI3);
    }
    return tex_z;
